    // CHI <-> flit 适配（HN 的旁路请求 / 响应回读）
    //------------------------------------------------------------------
    case2_chi_to_noc u_to_noc (
        .CLK         (CLK),
        .RST_N       (RST_N),
        .OPCODE      (adapter_opcode),
        .ADDR        (hn_addr | MEM_BASE),
        .SIZE        ({`C2_CHI_SIZE_W{1'b0}}),
        .QOS         ({`C2_CHI_QOS_W{1'b0}}),
