        .TXNID       (adapter_txnid_in),
        .RESP        (adapter_resp),
        .RESPERR     (adapter_resperr),
        .FWDSTATE    (),
        .DATA        (adapter_data),
        .BE          (adapter_be),
        .DBID        (adapter_dbid),
        .DATAID      (),
        .CHI_VALID   (adapter_chi_valid),
        .ORDER_ERR   (adapter_order_err),
        .CHI_LAST    (adapter_chi_last)
    );

    assign SNP_RX_READY = 1'b1;

endmodule
